import{_ as e,o,c as l,ag as i}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"角色立绘","description":"","frontmatter":{},"headers":[],"relativePath":"basics/sprites.md","filePath":"basics/sprites.md","lastUpdated":null}'),t={name:"basics/sprites.md"};function r(s,a,d,c,n,h){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="角色立绘" tabindex="-1">角色立绘 <a class="header-anchor" href="#角色立绘" aria-label="Permalink to &quot;角色立绘&quot;">​</a></h1><h2 id="什么是立绘" tabindex="-1">什么是立绘 <a class="header-anchor" href="#什么是立绘" aria-label="Permalink to &quot;什么是立绘&quot;">​</a></h2><p>立绘是角色的半身/全身图片，显示在 Galgame 覆盖层的左右两侧。当 AI 输出中提到角色及其表情时，对应的立绘会自动展示和切换。</p><h2 id="上传立绘" tabindex="-1">上传立绘 <a class="header-anchor" href="#上传立绘" aria-label="Permalink to &quot;上传立绘&quot;">​</a></h2><h3 id="单张上传" tabindex="-1">单张上传 <a class="header-anchor" href="#单张上传" aria-label="Permalink to &quot;单张上传&quot;">​</a></h3><ol><li>打开 <strong>资源管理器</strong></li><li>进入 <strong>立绘</strong> 分类</li><li>点击 <strong>上传</strong> 按钮</li><li>选择角色名并指定表情类型</li><li>选择图片文件（推荐透明背景 PNG）</li></ol><h3 id="批量上传" tabindex="-1">批量上传 <a class="header-anchor" href="#批量上传" aria-label="Permalink to &quot;批量上传&quot;">​</a></h3><ol><li>在资源管理器中选择 <strong>批量上传</strong></li><li>一次选择多张图片</li><li>插件会自动为每张图分配角色名和表情</li></ol><div class="tip custom-block"><p class="custom-block-title">推荐规格</p><ul><li>格式：PNG（透明背景）</li><li>分辨率：建议宽度 512px 以上</li></ul></div><h2 id="表情差分" tabindex="-1">表情差分 <a class="header-anchor" href="#表情差分" aria-label="Permalink to &quot;表情差分&quot;">​</a></h2><p>插件内置以下表情类型：</p><p><code>默认</code>、<code>微笑</code>、<code>生气</code>、<code>难过</code>、<code>惊讶</code>、<code>嘲讽</code>、<code>害羞</code>、<code>思考</code>、<code>大笑</code>、<code>搞怪</code></p><p>你也可以通过资源管理器添加自定义表情名称。</p><p>AI 在输出对话时会附带表情标签，插件会自动切换到对应的表情立绘。</p><h2 id="多角色同屏" tabindex="-1">多角色同屏 <a class="header-anchor" href="#多角色同屏" aria-label="Permalink to &quot;多角色同屏&quot;">​</a></h2><p>插件支持同时显示两个角色（左/右槽位）：</p><ul><li>当前说话的角色会高亮显示</li><li>非说话角色会略微变暗</li><li>当新角色出场时，最旧的非主角角色会自动退场</li></ul><h2 id="入场与退场动画" tabindex="-1">入场与退场动画 <a class="header-anchor" href="#入场与退场动画" aria-label="Permalink to &quot;入场与退场动画&quot;">​</a></h2><p>角色出场和退场时会有平滑的滑入/滑出动画效果。</p>',19)])])}const b=e(t,[["render",r]]);export{u as __pageData,b as default};
